package com.example.activite.web.controller;
import com.example.activite.domain.Reservation; import com.example.activite.service.IReservationService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.Parameter; import io.swagger.v3.oas.annotations.responses.*; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/reservations") @RequiredArgsConstructor @Tag(name="Réservations",description="Gestion des réservations") public class ReservationController { private final IReservationService reservationService;
@GetMapping @Operation(summary="Lister les réservations") @ApiResponse(responseCode="200",description="Liste retournée") public List<Reservation> findAll(){return reservationService.findAll();}
@GetMapping("/{id}") @Operation(summary="Consulter une réservation") @ApiResponses({@ApiResponse(responseCode="200",description="Réservation trouvée"),@ApiResponse(responseCode="404",description="Réservation introuvable")}) public Reservation findById(@Parameter(description="Identifiant de la réservation") @PathVariable Long id){return reservationService.findById(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Créer une réservation") @ApiResponses({@ApiResponse(responseCode="201",description="Réservation créée"),@ApiResponse(responseCode="400",description="Données invalides")}) public Reservation create(@RequestBody Reservation r){return reservationService.create(r);}
@PutMapping("/{id}") @Operation(summary="Modifier une réservation") @ApiResponses({@ApiResponse(responseCode="200",description="Réservation modifiée"),@ApiResponse(responseCode="400",description="Données invalides"),@ApiResponse(responseCode="404",description="Réservation introuvable")}) public Reservation update(@PathVariable Long id,@RequestBody Reservation r){return reservationService.update(id,r);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Supprimer une réservation") @ApiResponses({@ApiResponse(responseCode="204",description="Réservation supprimée"),@ApiResponse(responseCode="404",description="Réservation introuvable")}) public void deleteById(@PathVariable Long id){reservationService.deleteById(id);}}
